@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + controller : Controller
}

class Frame {
  - material : string
}

class Wheel {
  - diameter : double
}

class DriveSystem {
  + motor : Motor
}

class Motor {
  - power : double
}

class Battery {
  - energy : double
}

class Controller {
  + state : String
  + connectBattery(battery : Battery) : void
  + disconnectBattery() : void
  + commandDriveSystem() : void
}

abstract class AdvancedController extends Controller {
  + estimateNextInspectionDate() : Date
}

enum State {
  On
  Off
  Charging
}

@enduml

